package experiment

import (
	"fmt"
	"path/filepath"

	"github.com/DanielPopoola/index_lab/internal/btree"
)

// WorkloadResult contains statistics from a workload run.
type WorkloadResult struct {
	Pattern        KeyPattern
	InsertCount    int
	PageSplits     uint64
	PageWrites     uint64
	FinalHeight    int
	FinalPageCount int
}

// RunWorkload inserts n keys generated by pattern into a fresh B+ tree
// and reports the resulting statistics.
func RunWorkload(dir string, pattern KeyPattern, n int) (WorkloadResult, error) {
	dbPath := filepath.Join(dir, fmt.Sprintf("workload-%s.db", pattern))

	tree, err := btree.Open(dbPath)
	if err != nil {
		return WorkloadResult{}, err
	}
	defer tree.Close()

	keys := GenerateKeys(pattern, n)

	for _, key := range keys {

		if err := tree.Insert(key, key); err != nil {
			return WorkloadResult{}, fmt.Errorf("inserting key %d under pattern %s: %w", key, pattern, err)
		}
	}

	stats, err := tree.Stats()
	if err != nil {
		return WorkloadResult{}, err
	}

	return WorkloadResult{
		Pattern:        pattern,
		InsertCount:    len(keys),
		PageSplits:     stats.PageSplits,
		PageWrites:     stats.PageWrites,
		FinalHeight:    stats.Height,
		FinalPageCount: stats.TotalPages,
	}, nil
}

// RunAllWorkloads runs every KeyPattern and returns results in order:
// Sequential, Random, UUID4Like, UUID7Like.
func RunAllWorkloads(dir string, n int) ([]WorkloadResult, error) {
	patterns := []KeyPattern{Sequential, Random, UUID4Like, UUID7Like}

	results := make([]WorkloadResult, 0, len(patterns))
	for _, p := range patterns {
		result, err := RunWorkload(dir, p, n)
		if err != nil {
			return nil, err
		}
		results = append(results, result)
	}
	return results, nil
}
